// Offline copy of the whole kiosk.
// The page (not the service worker) downloads every file listed in
// precache.json into Cache Storage, so the boot screen can show real progress.
// sw.js then answers every request from that cache, network or not.
// precache.json is generated by tools/build_precache.py.

const PREFIX = 'hosun-fair-';
const MANIFEST = 'precache.json';
const PARALLEL = 4;

export const offlineSupported = 'caches' in window && 'serviceWorker' in navigator;

export async function registerWorker() {
  if (!offlineSupported) return null;
  try {
    return await navigator.serviceWorker.register('sw.js');
  } catch (error) {
    console.warn('[fair] service worker not registered', error);
    return null;
  }
}

async function readManifest() {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 6000);
  try {
    const res = await fetch(`${MANIFEST}?precache=${Date.now()}`, { cache: 'no-store', signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return { manifest: await res.clone().json(), response: res, online: true };
  } catch {
    const cached = await caches.match(MANIFEST, { ignoreSearch: true });
    return cached ? { manifest: await cached.json(), response: null, online: false } : { manifest: null, online: false };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Make sure every file is in the cache. Calls onProgress({ done, total, bytes, totalBytes }).
 * Resolves to { ok, version, missing, online, updated }.
 */
export async function prepareOffline(onProgress = () => {}) {
  if (!offlineSupported) return { ok: false, unsupported: true, missing: 0 };
  if (navigator.storage?.persist) navigator.storage.persist().catch(() => {});

  const { manifest, response, online } = await readManifest();
  if (!manifest) return { ok: false, missing: Infinity, online };

  const name = PREFIX + manifest.version;
  const cache = await caches.open(name);
  const files = manifest.files;
  const total = files.length;
  const totalBytes = files.reduce((sum, f) => sum + f.bytes, 0);
  let done = 0;
  let bytes = 0;
  let missing = 0;
  const report = () => onProgress({ done, total, bytes, totalBytes });

  const queue = [...files];
  const worker = async () => {
    for (let file = queue.shift(); file; file = queue.shift()) {
      if (!(await cache.match(file.url))) {
        try {
          // ?precache= tells sw.js to go to the network instead of answering from an older cache
          const res = await fetch(`${file.url}?precache=${manifest.version}`, { cache: 'no-cache' });
          if (!res.ok) throw new Error(`HTTP ${res.status}`);
          await cache.put(file.url, res);
        } catch (error) {
          missing += 1;
          console.warn('[fair] not cached:', file.url, error.message);
        }
      }
      done += 1;
      bytes += file.bytes;
      report();
    }
  };
  report();
  await Promise.all(Array.from({ length: PARALLEL }, worker));

  const ok = missing === 0;
  let updated = false;
  if (ok) {
    if (response) await cache.put(MANIFEST, response);
    // only now retire older copies, so a half-finished update never leaves the booth without one
    for (const key of await caches.keys()) {
      if (key.startsWith(PREFIX) && key !== name) {
        await caches.delete(key);
        updated = true;
      }
    }
  }
  return { ok, version: manifest.version, missing, online, updated, total, totalBytes };
}

export async function cacheStatus() {
  if (!offlineSupported) return { supported: false };
  const keys = (await caches.keys()).filter((k) => k.startsWith(PREFIX));
  const cached = await caches.match(MANIFEST, { ignoreSearch: true });
  const manifest = cached ? await cached.json() : null;
  let have = 0;
  if (manifest) {
    const cache = await caches.open(PREFIX + manifest.version);
    for (const f of manifest.files) if (await cache.match(f.url)) have += 1;
  }
  const estimate = await navigator.storage?.estimate?.().catch(() => null);
  const persisted = await navigator.storage?.persisted?.().catch(() => false);
  return { supported: true, caches: keys, version: manifest?.version, have, total: manifest?.files.length ?? 0, usage: estimate?.usage, persisted };
}

export async function clearOffline() {
  for (const key of await caches.keys()) if (key.startsWith(PREFIX)) await caches.delete(key);
}

// Video goes through a blob URL made from the cached file: Safari's <video>
// issues range requests that a service worker cannot reliably answer from cache.
const blobs = new Map();
export async function localUrl(url) {
  if (blobs.has(url)) return blobs.get(url);
  const hit = offlineSupported ? await caches.match(url, { ignoreSearch: true }) : null;
  if (!hit) return url;
  const objectUrl = URL.createObjectURL(await hit.blob());
  blobs.set(url, objectUrl);
  return objectUrl;
}
